<?php

namespace App\Http\Controllers;

use App\Models\LectureNote;
use App\Models\LectureSession;
use App\Services\LectureNoteGeneratorService;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\RedirectResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Str;
use Illuminate\View\View;
use Symfony\Component\HttpFoundation\StreamedResponse;

class LectureNoteController extends Controller
{
    public function __construct(
        protected LectureNoteGeneratorService $noteGenerator
    ) {}

    /**
     * Display a list of all notes generated by the authenticated student.
     */
    public function index(Request $request): View
    {
        $search = $request->query('search');

        $query = auth()->user()->lectureNotes()
            ->with(['session.subject', 'session.batch']);

        if ($search) {
            $query->where(function ($q) use ($search) {
                $q->where('title', 'like', "%{$search}%")
                    ->orWhere('content', 'like', "%{$search}%")
                    ->orWhereHas('session.subject', function ($sq) use ($search) {
                        $sq->where('subject_name', 'like', "%{$search}%")
                            ->orWhere('subject_code', 'like', "%{$search}%");
                    });
            });
        }

        $notes = $query->latest()->paginate(9)->withQueryString();

        return view('student.notes.index', compact('notes', 'search'));
    }

    /**
     * Generate or regenerate an AI-powered study note for a lecture session.
     */
    public function generate(Request $request, LectureSession $session): JsonResponse|RedirectResponse
    {
        if (! auth()->user()->canAccessLectures() && ! auth()->user()->isAdmin()) {
            abort(403, 'You must be a verified student to generate lecture study notes.');
        }

        $validated = $request->validate([
            'note_type' => ['nullable', 'string', 'in:summary,cheat_sheet,quiz_flashcards'],
        ]);

        $noteType = $validated['note_type'] ?? 'summary';

        $generated = $this->noteGenerator->generate($session, $noteType);

        $note = LectureNote::updateOrCreate(
            [
                'user_id' => auth()->id(),
                'session_id' => $session->id,
            ],
            [
                'title' => $generated['title'],
                'note_type' => $generated['note_type'],
                'key_takeaways' => $generated['key_takeaways'],
                'content' => $generated['content'],
            ]
        );

        if ($request->wantsJson()) {
            return response()->json([
                'success' => true,
                'message' => 'Lecture note synthesized successfully!',
                'note' => [
                    'id' => $note->id,
                    'title' => $note->title,
                    'note_type' => $note->note_type,
                    'badge' => $note->note_type_badge,
                    'key_takeaways' => $note->key_takeaways,
                    'content' => $note->content,
                    'student_notes' => $note->student_notes,
                    'updated_at' => $note->updated_at->diffForHumans(),
                ],
            ]);
        }

        return redirect()->route('lectures.show', $session)
            ->with('status', 'AI Study Note generated successfully! Check the Smart Notes tab below.');
    }

    /**
     * Update student personal annotations on an existing note.
     */
    public function update(Request $request, LectureNote $note): JsonResponse|RedirectResponse
    {
        if ($note->user_id !== auth()->id()) {
            abort(403, 'Unauthorized action.');
        }

        $validated = $request->validate([
            'student_notes' => ['nullable', 'string', 'max:50000'],
        ]);

        $note->update([
            'student_notes' => $validated['student_notes'],
        ]);

        if ($request->wantsJson()) {
            return response()->json([
                'success' => true,
                'message' => 'Personal annotations saved!',
                'student_notes' => $note->student_notes,
            ]);
        }

        return back()->with('status', 'Your personalized lecture notes have been saved.');
    }

    /**
     * Export / download the note as a formatted Markdown (.md) file.
     */
    public function download(LectureNote $note): StreamedResponse
    {
        if ($note->user_id !== auth()->id() && ! auth()->user()->isAdmin()) {
            abort(403, 'Unauthorized to download this note.');
        }

        $note->load(['session.subject', 'session.batch']);

        $filename = Str::slug($note->title).'.md';

        $exportContent = $note->content;

        if ($note->student_notes) {
            $exportContent .= "\n\n---\n\n### ✍️ My Personal Annotations & Review Remarks\n\n".$note->student_notes;
        }

        $exportContent .= "\n\n---\n*Generated by UniReplay AI Academic Study Engine for ".auth()->user()->name.' on '.now()->format('Y-m-d').'*';

        return response()->streamDownload(function () use ($exportContent) {
            echo $exportContent;
        }, $filename, [
            'Content-Type' => 'text/markdown; charset=UTF-8',
        ]);
    }
}
